"use client"

import { useState, useRef } from "react"

import { Card } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Pill, Trash2, Minus, Plus, AlertTriangle, Check } from "lucide-react"
import { toast } from "react-toastify"
import type { FormAction } from "@/lib/form-storage"
import { useRemoveProductFromVisitDepartment, useUpdateProductQuantity } from "@/hooks/visits"
import { useConfirmVisitDepartmentProduct } from "@/hooks/billing/hooks"

interface FormActionsDisplayProps {
  items: FormAction[]
  label?: string
  hideLabel?: boolean
  bold?: boolean
  center?: boolean
  italic?: boolean
  underline?: boolean
  visitId?: string
  departmentId?: string
  onRemove?: (id: string) => void
  onRestore?: (id: string) => void
  onUpdateQuantity?: (id: string, quantity: number) => void
  readOnly?: boolean
}

export default function FormActionsDisplay({
  items,
  label = "Products",
  hideLabel = false,
  bold = false,
  center = false,
  italic = false,
  underline = false,
  visitId,
  departmentId,
  onRemove,
  onRestore,
  onUpdateQuantity,
  readOnly = false,
}: FormActionsDisplayProps) {
  const { updateQuantity } = useUpdateProductQuantity()
  const { removeProduct } = useRemoveProductFromVisitDepartment()
  const { confirmVisitDepartmentProduct } = useConfirmVisitDepartmentProduct()
  const [confirmedIds, setConfirmedIds] = useState<Set<string>>(new Set())
  // Track which item's qty is being directly edited, and the draft string value
  const [editingId, setEditingId] = useState<string | null>(null)
  const [draftQty, setDraftQty] = useState<string>('')
  // Track which item has an in-flight backend request so its controls disable
  const [busyId, setBusyId] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const canUseServer = Boolean(visitId && departmentId)

  const updateServerQuantity = async (item: FormAction, nextQty: number) => {
    if (!canUseServer) {
      onUpdateQuantity && onUpdateQuantity(item.id, nextQty)
      return
    }

    setBusyId(item.id)
    try {
      
      
      
      
      
      

      if (!item.backendId) {
        throw new Error(`No backendId found for item: ${item.name}. This item may not have been properly added to the visit.`)
      }

      await updateQuantity(item.backendId, nextQty)
      onUpdateQuantity && onUpdateQuantity(item.id, nextQty)
    } catch (e) {
      console.error('update quantity error', e)
    } finally {
      setBusyId(null)
    }
  }

  const removeServerItem = async (item: FormAction) => {
    if (!canUseServer) {
      onRemove && onRemove(item.id)
      return
    }

    setBusyId(item.id)
    try {
      if (!item.backendId) {
        throw new Error(`No backendId found for item: ${item.name}`)
      }
      
      
      
      const response = await removeProduct(item.backendId)
      
      
      
      if (response?.status !== 'SUCCESS') {
        throw new Error(response?.message || 'Failed to remove visit department product')
      }
      onRemove && onRemove(item.id)
    } catch (e) {
      console.error('remove item error', e)
    } finally {
      setBusyId(null)
    }
  }
  const renderItem = (item: FormAction) => {
    const isRemoved = item.removedFromVisit === true

    return (
      <div
        key={item.id}
        className={`group rounded-lg border transition-all duration-200 overflow-hidden ${
          isRemoved
            ? 'bg-amber-50/80 dark:bg-amber-950/30 border-amber-300 dark:border-amber-500/40'
            : 'bg-white dark:bg-slate-900 border-orange-100 dark:border-orange-900/30 hover:border-orange-300 dark:hover:border-orange-700/50 hover:shadow-sm'
        }`}
      >
        {/* Always-visible compact row */}
        <div className="flex items-center justify-between gap-2 px-3 py-2">
          <div className="flex items-center gap-2 min-w-0 flex-1">
            {isRemoved && (
              <AlertTriangle className="h-3 w-3 shrink-0 text-amber-500" />
            )}
            <p className={`text-sm font-medium truncate leading-tight ${isRemoved ? 'line-through text-muted-foreground' : ''}`}>
              {item.name}
            </p>
            {item.billingConfirmationStatus === "PENDING_OPERATOR_CONFIRMATION" &&
              !confirmedIds.has(item.id) && (
                <span className="shrink-0 text-[11px] bg-amber-100 text-amber-800 dark:bg-amber-900/40 dark:text-amber-300 px-1.5 py-0.5 rounded-full font-medium">
                  Added in Billing
                </span>
              )}
            {(confirmedIds.has(item.id) ||
              item.billingConfirmationStatus === "CONFIRMED" ||
              item.confirmedByName) && (
              <span className="shrink-0 text-[11px] bg-emerald-100 text-emerald-800 dark:bg-emerald-900/40 dark:text-emerald-300 px-1.5 py-0.5 rounded-full font-medium">
                {item.confirmedByName
                  ? `Confirmed by ${item.confirmedByName}`
                  : "Confirmed"}
              </span>
            )}
          </div>
          <div className="flex items-center gap-1.5 shrink-0">
            {/* Quantity pill — always visible */}
            <span className="text-xs font-semibold tabular-nums text-muted-foreground bg-muted/60 rounded-full px-2 py-0.5 leading-none">
              ×{item.quantity}
            </span>
            {item.billingConfirmationStatus === "PENDING_OPERATOR_CONFIRMATION" &&
              !confirmedIds.has(item.id) &&
              item.backendId && (
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  className="h-6 text-[12px] px-2 text-emerald-700 dark:text-emerald-300 border-emerald-300 dark:border-emerald-700 bg-emerald-50 dark:bg-emerald-900/30 hover:bg-emerald-100 dark:hover:bg-emerald-900/50 gap-1 font-medium"
                  disabled={busyId === item.id}
                  onClick={async (e) => {
                    e.stopPropagation()
                    if (!item.backendId) return
                    setBusyId(item.id)
                    try {
                      const res = await confirmVisitDepartmentProduct(item.backendId)
                      if (res.status === "SUCCESS") {
                        toast.success("Product accepted")
                        setConfirmedIds((prev) => new Set([...prev, item.id]))
                      } else {
                        toast.error(res.message || "Failed to accept product")
                      }
                    } catch (err) {
                      console.error("Error accepting product:", err)
                      toast.error("Failed to accept product")
                    } finally {
                      setBusyId(null)
                    }
                  }}
                >
                  <Check className="h-3 w-3" />
                  Accept
                </Button>
              )}
          </div>
        </div>

        {/* Hover-only controls — collapses to 0 height by default */}
        {readOnly ? (
          <div className="px-3 pb-2 pt-0">
            <div className="flex items-center justify-between gap-2">
              <div />
              <span className="text-xs text-muted-foreground">{isRemoved ? 'Removed' : 'Saved'}</span>
            </div>
          </div>
        ) : (
          <div className="grid grid-rows-[0fr] group-hover:grid-rows-[1fr] transition-[grid-template-rows] duration-200">
            <div className="overflow-hidden">
              <div className={`flex items-center justify-between gap-2 px-3 pb-2 pt-0 ${isRemoved ? 'opacity-60' : ''}`}>
              {/* Quantity stepper */}
              {item.isQuantifiable !== false ? (
                <div className="flex items-center gap-1">
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-6 w-6 p-0 rounded-full"
                    disabled={isRemoved || busyId === item.id}
                    onClick={() => {
                      if (isRemoved || busyId === item.id) return
                      const next = Math.max(1, item.quantity - 1)
                      canUseServer && item.backendId
                        ? updateServerQuantity(item, next)
                        : onUpdateQuantity?.(item.id, next)
                    }}
                  >
                    <Minus className="h-3 w-3" />
                  </Button>

                  {/* Inline editable quantity — click to type directly */}
                  {editingId === item.id ? (
                    <input
                      ref={inputRef}
                      type="number"
                      min={1}
                      value={draftQty}
                      disabled={busyId === item.id}
                      onChange={(e) => setDraftQty(e.target.value)}
                      onFocus={(e) => e.target.select()}
                      onBlur={() => {
                        const parsed = parseInt(draftQty, 10)
                        const next = Number.isFinite(parsed) && parsed >= 1 ? parsed : item.quantity
                        if (next !== item.quantity) {
                          canUseServer && item.backendId
                            ? updateServerQuantity(item, next)
                            : onUpdateQuantity?.(item.id, next)
                        }
                        setEditingId(null)
                      }}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          ;(e.target as HTMLInputElement).blur()
                        }
                        if (e.key === 'Escape') {
                          setEditingId(null)
                        }
                      }}
                      className="w-8 text-center text-xs font-medium tabular-nums bg-transparent border-b border-primary/60 outline-none focus:border-primary [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
                    />
                  ) : (
                    <span
                      className="text-xs tabular-nums font-medium w-8 text-center cursor-text hover:text-primary transition-colors select-none"
                      title="Click to edit quantity"
                      onClick={() => {
                        if (isRemoved || busyId === item.id) return
                        setDraftQty(String(item.quantity))
                        setEditingId(item.id)
                        // focus after render
                        setTimeout(() => inputRef.current?.focus(), 0)
                      }}
                    >
                      {item.quantity}
                    </span>
                  )}

                  <Button
                    variant="outline"
                    size="sm"
                    className="h-6 w-6 p-0 rounded-full"
                    disabled={isRemoved || busyId === item.id}
                    onClick={() => {
                      if (isRemoved || busyId === item.id) return
                      const next = item.quantity + 1
                      canUseServer && item.backendId
                        ? updateServerQuantity(item, next)
                        : onUpdateQuantity?.(item.id, next)
                    }}
                  >
                    <Plus className="h-3 w-3" />
                  </Button>
                </div>
              ) : (
                <div />
              )}

              {/* Right-side actions */}
              <div className="flex items-center gap-1">
                {isRemoved && onRestore ? (
                  <Button
                    variant="secondary"
                    size="sm"
                    className="h-6 px-2 text-[12px]"
                    onClick={() => onRestore(item.id)}
                  >
                    Restore
                  </Button>
                ) : null}
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-6 w-6 p-0 text-destructive hover:bg-destructive/10 hover:text-destructive"
                  disabled={busyId === item.id}
                  onClick={() => {
                    if (isRemoved) {
                      onRemove?.(item.id)
                      return
                    }
                    canUseServer && item.backendId
                      ? removeServerItem(item)
                      : onRemove?.(item.id)
                  }}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              </div>
              </div>
            </div>
          </div>
        )}
      </div>
    )
  }

  return (
    <div className="space-y-3">
      {!hideLabel && (
        <label
          className={`text-sm font-medium flex items-center gap-2 ${bold ? 'font-bold' : ''} ${center ? 'justify-center' : ''} ${italic ? 'italic' : ''} ${underline ? 'underline' : ''}`}
        >
          <Pill className="h-4 w-4 text-orange-500" />
          {label}
        </label>
      )}
      <Card className="p-3 bg-orange-50 dark:bg-orange-950/20 border-orange-200 dark:border-orange-900/30">
        {items.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
            {items.map(renderItem)}
          </div>
        ) : (
          <div className="text-center py-5">
            <p className="text-sm text-muted-foreground">No products added yet</p>
          </div>
        )}
      </Card>
    </div>
  )
}
